WITH exploded AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(discounts) li AS val), valid AS (SELECT *, COALESCE(val, 0) AS val_filled, TRIM(currency) AS clean_currency FROM exploded WHERE effective_from >= DATE '2024-06-05' AND val <= 80), enriched AS (SELECT plan, effective_from, val, val_filled, clean_currency, DENSE_RANK() OVER (PARTITION BY plan ORDER BY val_filled DESC) AS val_filled_dense_rank, COUNT(val) OVER (PARTITION BY currency) AS currency_count_val, COUNT(val_filled) OVER (PARTITION BY currency) AS currency_count_val_filled, RANK() OVER (PARTITION BY plan ORDER BY val DESC NULLS FIRST) AS val_rank FROM valid WHERE val_filled IS NULL), scored AS (SELECT *, RANK() OVER (PARTITION BY plan ORDER BY val_filled) AS val_filled_rank FROM enriched) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count, APPROX_PERCENTILE(currency_count_val_filled, ARRAY(0.25, 0.5, 0.75)) AS currency_count_val_filled_quartiles, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count FROM scored GROUP BY 1 HAVING COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) > 1
